test("Studio uses configured allocations, including smaller ones, and falls back for unlisted tenants", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(book("orchid")), {status: "booked", id: "orchid", remaining: 1});
  assert.deepEqual(dispatch(book("fern", "fern", 4)), {status: "full", id: "fern", remaining: 3});
  assert.deepEqual(dispatch(book("iris", "iris", 6)), {status: "full", id: "iris", remaining: 5});
  assert.equal(dispatch(book("iris", "iris", 5)).status, "booked");
});

test("renewals use the previous tenant's allocation and share tenant/day accounting", () => {
  const dispatch = planner(catalog);
  dispatch(book("seed"));
  assert.deepEqual(dispatch(renew("seed", "may")), {status: "booked", id: "may", remaining: 1});
  assert.equal(dispatch(renew("seed", "may")).status, "replay");
  assert.equal(dispatch(renew("seed", "may", "2025-05-02", 6)).status, "conflict");
  assert.deepEqual(dispatch(renew("seed", "extra", "2025-05-02", 2)),
    {status: "full", id: "extra", remaining: 1});
  assert.equal(dispatch(renew("seed", "extra", "2025-05-02", 1)).status, "booked");
  dispatch(book("iris", "iris", 5));
  assert.deepEqual(dispatch(renew("iris", "iris-may", "2025-05-02", 6)),
    {status: "full", id: "iris-may", remaining: 5});
  dispatch(book("fern", "fern", 3));
  assert.deepEqual(dispatch(renew("fern", "fern-may", "2025-05-02", 4)),
    {status: "full", id: "fern-may", remaining: 3});
});

test("replays, conflicts and cancellations precede admission, even for imported over-capacity IDs", () => {
  const dispatch = planner(catalog);
  const request = book("imported", "orchid", 12);
  assert.equal(dispatch({...request, action: "import"}).status, "imported");
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units: 11}).status, "conflict");
  assert.deepEqual(dispatch(book("blocked", "orchid", 1)), {status: "full", id: "blocked", remaining: 0});
  assert.equal(dispatch({service: "studio", action: "cancel", id: "imported"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({service: "studio", action: "cancel", id: "imported"}).status, "replay");
  assert.equal(dispatch(renew("imported", "next")).status, "missing");
  assert.equal(dispatch(book("replacement", "orchid", 8)).status, "booked");
});

test("usage is scoped to tenant, day and desk; invalid requests do not enter the ledger", () => {
